insert into public.qd_characters (id,name,animal_type,primary_color,secondary_color,unlock_xp,rarity,image_url,is_legendary,content) values ('tilmash','Тілмаш','{"ru":"Түлкі · Лиса","en":"Түлкі · Fox"}','#df7948','#fff0d5','0','common','/characters/tilmash.svg','false','{"id":"tilmash","name":"Тілмаш","animalType":{"ru":"Түлкі · Лиса","en":"Түлкі · Fox"},"description":{"ru":"Коллекционирует слова и превращает каждое из них в маленькое открытие.","en":"Collects words and turns each one into a little discovery."},"personality":{"ru":"Умный, любознательный, внимательный к деталям.","en":"Clever, curious and attentive to detail."},"quirk":{"ru":"Шевелит ушами и открывает карманный словарь.","en":"Twitches his ears and opens a pocket dictionary."},"primaryColor":"#df7948","secondaryColor":"#fff0d5","rarity":"common","line":{"ru":"Сәлем! Давайте найдём смысл нового слова.","en":"Сәлем! Let’s discover what a new word means."},"support":{"ru":"Посмотрим в словарь вместе. Ошибка — начало открытия.","en":"Let’s check the dictionary together. A mistake begins a discovery."},"success":{"ru":"Дұрыс! Ещё одно слово в нашей коллекции.","en":"Дұрыс! One more word in our collection."},"unlockXP":0,"imageUrl":"/characters/tilmash.svg","animationUrls":{},"isLegendary":false,"dialogueLines":{"greeting":{"ru":"Сәлем! Давайте найдём смысл нового слова.","en":"Сәлем! Let’s discover what a new word means."},"waiting":{"ru":"Я рядом. Продолжайте, когда будете готовы.","en":"I’m here. Continue when you feel ready."},"thinking":{"ru":"Сәлем! Давайте найдём смысл нового слова.","en":"Сәлем! Let’s discover what a new word means."},"joy":{"ru":"Дұрыс! Ещё одно слово в нашей коллекции.","en":"Дұрыс! One more word in our collection."},"support":{"ru":"Посмотрим в словарь вместе. Ошибка — начало открытия.","en":"Let’s check the dictionary together. A mistake begins a discovery."},"celebration":{"ru":"Жаңа деңгей! Празднуем ваши новые знания.","en":"Жаңа деңгей! Let’s celebrate your new knowledge."},"sleep":{"ru":"Демалайық. Отдых тоже помогает учиться.","en":"Демалайық. Rest helps us learn too."},"running":{"ru":"Кеттік! Читайте внимательно, таймер не страшен.","en":"Кеттік! Read carefully. The timer is nothing to fear."},"victory":{"ru":"Дұрыс! Ещё одно слово в нашей коллекции.","en":"Дұрыс! One more word in our collection."}}}') on conflict do nothing;
